create table if not exists public.agent_evaluations(id uuid primary key default gen_random_uuid(), user_id uuid not null references auth.users(id) on delete cascade, subject_id uuid not null references public.subjects(id) on delete cascade, unit_id text, conversation_id uuid references public.conversations(id) on delete set null, agent_id text not null, criterion text not null, score numeric not null check(score between 0 and 1), confidence numeric not null default .2 check(confidence between 0 and 1), evidence text, created_at timestamptz not null default now());
create index if not exists agent_evaluations_profile_idx on public.agent_evaluations(user_id,subject_id,created_at desc);
create table if not exists public.learning_dimensions(id uuid primary key default gen_random_uuid(), user_id uuid not null references auth.users(id) on delete cascade, subject_id uuid references public.subjects(id) on delete cascade, dimension text not null check(dimension in ('autonomy','precision','reasoning','creativity','application','critical_thinking','communication','metacognition','retention','consistency')), score numeric not null default .5 check(score between 0 and 1), confidence numeric not null default .2 check(confidence between 0 and 1), evidence_count integer not null default 0, trend numeric not null default 0, updated_at timestamptz not null default now(), unique(user_id,subject_id,dimension));
create table if not exists public.learning_recommendations(id uuid primary key default gen_random_uuid(), user_id uuid not null references auth.users(id) on delete cascade, subject_id uuid references public.subjects(id) on delete cascade, dimension text, objective text not null, action text not null, metric text not null, target numeric, status text not null default 'active' check(status in ('active','completed','dismissed')), created_at timestamptz not null default now());
alter table public.agent_evaluations enable row level security; alter table public.learning_dimensions enable row level security; alter table public.learning_recommendations enable row level security;
create policy agent_evaluations_owner on public.agent_evaluations for all using(user_id=auth.uid()) with check(user_id=auth.uid()); create policy learning_dimensions_owner on public.learning_dimensions for all using(user_id=auth.uid()) with check(user_id=auth.uid()); create policy learning_recommendations_owner on public.learning_recommendations for all using(user_id=auth.uid()) with check(user_id=auth.uid());
